// 📊 COLLECTEUR - Accès correct aux données webhook
const webhookData = $input.item.json.body;

console.log('📊 COLLECTEUR:');
console.log('- Contenu extrait:', !!webhookData?.contenu);
console.log('- Taille:', webhookData?.contenu?.length);

if (!webhookData?.contenu) {
  throw new Error('Contenu manquant: ' + JSON.stringify($input.item.json));
}

return {
  json: {
    contenu_original: webhookData.contenu,
    subtitle_original: webhookData.subtitle || '',
    collecteur_status: 'webhook_extracted',
    timestamp: new Date().toISOString()
  },
  binary: $input.item.binary || {}
};

// 🔗 FUSION - STRUCTURE OPENAI CORRIGÉE
const allInputs = $input.all();
console.log('🔗 FUSION - Analyse inputs:', allInputs.length);

// Identifier les données par signature
let collectorData = null;
let openAIData = null;

allInputs.forEach((input, index) => {
  console.log(`Input ${index}:`, {
    hasJson: !!input.json,
    isCollector: !!(input.json?.collecteur_status),
    hasMessage: !!(input.json?.message),
    hasIndex: !!(input.json?.index !== undefined),
    keys: input.json ? Object.keys(input.json) : []
  });

  // Collecteur = a collecteur_status
  if (input.json?.collecteur_status === 'webhook_extracted') {
    collectorData = input;
    console.log('✅ COLLECTEUR IDENTIFIÉ');
  }

  // OpenAI = structure avec message + index + finish_reason
  if (input.json?.message && input.json?.index !== undefined && input.json?.finish_reason) {
    openAIData = input;
    console.log('✅ OPENAI IDENTIFIÉ - nouvelle structure');
  }
});

// Validation
if (!collectorData) {
  throw new Error('Données collecteur manquantes');
}

if (!openAIData) {
  throw new Error('Données OpenAI manquantes - structure: ' + JSON.stringify(allInputs.map(i => i.json ? Object.keys(i.json) : 'no json')));
}

// Parse OpenAI - NOUVELLE STRUCTURE
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = collectorData.json.contenu_original;

// Accès direct à message.content (pas d'array)
const aiResponse = openAIData.json.message?.content;
if (aiResponse) {
  console.log('🤖 AI RESPONSE:', aiResponse.substring(0, 200));

  try {
    const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleanResponse);

    aiTitle = analysis.title || aiTitle;
    aiSubtitle = analysis.subtitle || aiSubtitle;
    aiBody = analysis.body || aiBody;

    console.log('✅ AI PARSING SUCCESS:', { title: aiTitle, subtitle: aiSubtitle });
  } catch (e) {
    console.log('❌ AI PARSING FAILED:', e.message);
    console.log('Raw response was:', aiResponse);
  }
} else {
  console.log('❌ Pas de message.content dans OpenAI data');
}

// Résultat final
const result = {
  json: {
    // Données originales
    contenu_original: collectorData.json.contenu_original,
    subtitle_original: collectorData.json.subtitle_original,

    // Données IA
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    // Debug
    debug: {
      inputs_count: allInputs.length,
      collector_found: !!collectorData,
      openai_found: !!openAIData,
      openai_structure: openAIData ? Object.keys(openAIData.json) : [],
      ai_parsing_success: aiTitle !== 'Titre par défaut',
      binary_preserved: !!(collectorData.binary && Object.keys(collectorData.binary).length > 0),
      binary_count: collectorData.binary ? Object.keys(collectorData.binary).length : 0
    }
  },
  binary: collectorData.binary || {}
};

console.log('🎯 FUSION RESULT:');
console.log('- AI Title:', result.json.ai_title);
console.log('- AI Subtitle:', result.json.ai_subtitle);
console.log('- Binary count:', result.json.debug.binary_count);

return result;

// ✅ RÉSULTAT FINAL
const flaskResponse = $input.item.json;
const fusionData = $input.first();

if (flaskResponse?.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document créé avec IA + images !',
      project_id: flaskResponse.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResponse.project_id}`,

      ai_content: {
        title: fusionData?.json?.ai_title,
        subtitle: fusionData?.json?.ai_subtitle,
        body_preview: fusionData?.json?.ai_body?.substring(0, 150) + '...'
      },

      technical: fusionData?.json?.debug
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResponse?.error || 'Erreur Flask',
    debug: {
      flask_response: flaskResponse,
      fusion_debug: fusionData?.json?.debug
    }
  }
};
